use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Semaphore {
    permits: Mutex<usize>,
    available: Condvar,
}

impl Semaphore {
    fn new() -> Self {
        Self {
            permits: Mutex::new(0),
            available: Condvar::new(),
        }
    }

    fn release(&self) {
        let mut permits = self.permits.lock().unwrap();
        *permits += 1;
        self.available.notify_one();
    }

    fn acquire(&self) {
        let mut permits = self.permits.lock().unwrap();
        while *permits == 0 {
            permits = self.available.wait(permits).unwrap();
        }
        *permits -= 1;
    }
}

struct Shared {
    a: Mutex<()>,
    b: Mutex<()>,
    sa: Semaphore,
    sb: Semaphore,
    flag: AtomicUsize,
}

fn a(shared: Arc<Shared>) -> usize {
    let first_a = shared.a.lock().unwrap();
    shared.sa.release();
    shared.sb.acquire();

    let second_b = shared.b.lock().unwrap();
    shared.flag.fetch_add(1, Ordering::SeqCst);

    drop(second_b);
    drop(first_a);
    1
}

fn b(shared: Arc<Shared>) -> usize {
    let first_b = shared.b.lock().unwrap();
    shared.sb.release();
    shared.sa.acquire();

    // Release b before acquiring the locks in the common a-then-b order.
    drop(first_b);
    let first_a = shared.a.lock().unwrap();
    let second_b = shared.b.lock().unwrap();
    shared.flag.fetch_add(1, Ordering::SeqCst);

    drop(second_b);
    drop(first_a);
    1
}

fn bystander(progress: Arc<AtomicUsize>) {
    loop {
        progress.fetch_add(1, Ordering::Relaxed);
        thread::yield_now();
    }
}

fn main() {
    let shared = Arc::new(Shared {
        a: Mutex::new(()),
        b: Mutex::new(()),
        sa: Semaphore::new(),
        sb: Semaphore::new(),
        flag: AtomicUsize::new(0),
    });

    let progress = Arc::new(AtomicUsize::new(0));
    let bystander_progress = Arc::clone(&progress);
    let _bystander_handle = thread::spawn(move || bystander(bystander_progress));

    // Ensure the bystander has started making progress before starting the workers.
    while progress.load(Ordering::Relaxed) == 0 {
        thread::yield_now();
    }

    let shared_a = Arc::clone(&shared);
    let worker_a = thread::spawn(move || a(shared_a));

    let shared_b = Arc::clone(&shared);
    let worker_b = thread::spawn(move || b(shared_b));

    let result_a = worker_a.join().unwrap();
    let result_b = worker_b.join().unwrap();

    println!("DONE a={result_a} b={result_b}");
}
